from robot.errors import ExecutionFailed
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.ettf.utils.robot_handlers import DynamicKeyword, TeardownKeywordDecorator
from taf.ul.ettf.events.notifier import Notifier
from taf.ul.ettf.events.comparator import On
from taf.ul.ettf.events.lifetime_policy import OneTimeCall
from taf.ul.ettf.events.move_policy import AlwaysMove
from taf.ul.ettf.events.event import RetryContextFailed, Teardown
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.typed.custom_types import RobotKeyword


logger = custom_logger('retry_context')
notifier = Notifier()


class RobotCallable(object):
    def __init__(self, keyword, args=None):
        self.__name__ = keyword
        self.keyword = keyword
        self.args = args if args else []

    def __call__(self):
        BuiltIn().run_keyword(self.keyword, *self.args)

    def __repr__(self):
        return self.keyword


class Cleanup(object):
    __name__ = 'Cleanup'

    def __call__(self):
        # clear additional registers, etc.
        logger.info('RetryManagerCleanup')


def run_keywords(keywords):
    if 'AND' not in keywords:
        BuiltIn().run_keyword(*keywords)
    else:
        BuiltIn().run_keywords(*keywords)


def with_retry_context(retries, *keywords):
    retries = int(retries)

    for retry_idx in range(retries):
        notifier.open_group('retry_context_attempt_{}'.format(retry_idx), move_policy=AlwaysMove())
        notifier.register(Cleanup(), On(RetryContextFailed), OneTimeCall())

        with DynamicKeyword('Attempt {}'.format(retry_idx + 1)) as keyword:
            try:
                logger.info('Attempt: {}'.format(retry_idx + 1))
                run_keywords(keywords)
                keyword.passed()
                break
            except ExecutionFailed as err:
                logger.error('Error occurred during retry attempt: {}'.format(err))
                Notifier().notify(Teardown(False), TeardownKeywordDecorator())
                Notifier().notify(RetryContextFailed(), TeardownKeywordDecorator())
                keyword.failed()
            finally:
                notifier.close_active_group()

    if not keyword.is_passed():
        raise ExecutionFailed('Test failed')


@typed(keyword=RobotKeyword(), teardown=RobotKeyword())
def with_teardownable(keyword, teardown):
    notifier.register(RobotCallable(teardown.name(), teardown.args()), On(Teardown), OneTimeCall())
    BuiltIn().run_keyword(keyword.name(), *keyword.args())
